def get(self, key: str):
    path = self._path(key)
    if not os.path.exists(path):
        return None
    with open(path) as f:
        entry = json.load(f)
    if time.time() - entry["ts"] > self.ttl:
        try:
            os.remove(path)
        except OSError:
            pass
        return None
    return entry["val"]

def get(self, key, default=None):
    p = self._path(key)
    if not os.path.exists(p):
        return default
    with open(p) as f:
        rec = json.load(f)
    if self._now() - rec["t"] > self.ttl:
        try:
            os.remove(p)
        except OSError:
            pass
        return default
    return rec["v"]
